        move    x:(r7+$01),a
        add     #>$1800,a
        move    a1,r4
        move    #>$7ff,m4
        move    #>$ffffff,n1
        do      n7,>rzdend
        move    x:(r7+$04),a
        move    x:(r7+$05),b
        move    x:(r7+$06),b0
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b1,x:(r7+$05)
        move    b0,x:(r7+$06)
        move    x:(r7+$07),a
        move    x:(r7+$08),b
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b,x:(r7+$08)
        move    x:(r7+$0c),a
        move    x:(r7+$0d),b
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b,x:(r7+$0d)
        move    x:(r7+$10),a
        move    x:(r7+$11),b
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b,x:(r7+$11)
; ---- DTND: main read at P, gain, loop lowpass ----
        move    x:(r7+$05),a
        move    a1,b
        asr     #$d,a,a
        move    a1,a  ; drop the fraction asr left in a0
        and     #>$001fff,b
        asl     #$a,b,b
        move    b1,y1
        neg     a
        move    a1,n5
        lua     (r5+n5),r1
        move    y:(r1)+n1,x0
        move    y:(r1),a
        sub     x0,a
        move    a,x1
        mpy     y1,x1,a
        add     x0,a
        move    a,x0
        move    x:(r7+$0b),y1
        mpy     x0,y1,a  ; g o
        move    x:(r7+$1a),x0
        sub     x0,a
        move    a,x1
        move    x:(r7+$0f),y1
        mpy     y1,x1,a
        add     x0,a
        move    a,x:(r7+$1a)  ; loop lowpass state
        move    a,x:(r7+$19)  ; v
        move    x:(r7+$05),x0
        move    x:(r7+$08),y0
        mpy     y0,x0,b
        move    b,x:(r7+$1c)  ; P det / 1024
; allpass 1
        move    x:(r7+$1c),x0
        move    #>$400000,y0
        mpy     y0,x0,a
        add     #>$002000,a  ; +1 sample
        move    a1,b
        asr     #$d,a,a
        move    a1,a  ; drop the fraction asr left in a0
        and     #>$001fff,b
        asl     #$a,b,b
        move    b1,y1
        neg     a
        move    a1,n2
        lua     (r2+n2),r1
        move    y:(r1)+n1,x0
        move    y:(r1),a
        sub     x0,a
        move    a,x1
        mpy     y1,x1,a
        add     x0,a
        move    a,x0  ; d
        move    x:(r7+$19),a
        move    #>$266666,y1
        mac     -x0,y1,a  ; in = v - .3 d
        move    a,y:(r2)+
        move    a,x1
        move    x0,a
        mac     y1,x1,a  ; v = d + .3 in
        move    a,x:(r7+$19)
        move    a,x:(r7+$12)  ; u1: the string after allpass 1
; allpass 2
        move    x:(r7+$1c),x0
        move    #>$3fe0df,y0
        mpy     y0,x0,a
        add     #>$002000,a  ; +1 sample
        move    a1,b
        asr     #$d,a,a
        move    a1,a  ; drop the fraction asr left in a0
        and     #>$001fff,b
        asl     #$a,b,b
        move    b1,y1
        neg     a
        move    a1,n3
        lua     (r3+n3),r1
        move    y:(r1)+n1,x0
        move    y:(r1),a
        sub     x0,a
        move    a,x1
        mpy     y1,x1,a
        add     x0,a
        move    a,x0  ; d
        move    x:(r7+$19),a
        move    #>$266666,y1
        mac     -x0,y1,a  ; in = v - .3 d
        move    a,y:(r3)+
        move    a,x1
        move    x0,a
        mac     y1,x1,a  ; v = d + .3 in
        move    a,x:(r7+$19)
        move    a,x:(r7+$13)  ; u2: the string after allpass 2
; allpass 3
        move    x:(r7+$1c),x0
        move    #>$3fb98c,y0
        mpy     y0,x0,a
        add     #>$002000,a  ; +1 sample
        move    a1,b
        asr     #$d,a,a
        move    a1,a  ; drop the fraction asr left in a0
        and     #>$001fff,b
        asl     #$a,b,b
        move    b1,y1
        neg     a
        move    a1,n4
        lua     (r4+n4),r1
        move    y:(r1)+n1,x0
        move    y:(r1),a
        sub     x0,a
        move    a,x1
        mpy     y1,x1,a
        add     x0,a
        move    a,x0  ; d
        move    x:(r7+$19),a
        move    #>$266666,y1
        mac     -x0,y1,a  ; in = v - .3 d
        move    a,y:(r4)+
        move    a,x1
        move    x0,a
        mac     y1,x1,a  ; v = d + .3 in
        move    a,x:(r7+$19)
; side = 0.6 * SIDE * (u1 - u2) (no DC in it: both taps carry the same)
        move    x:(r7+$12),a
        move    x:(r7+$13),x0
        sub     x0,a
        move    a,x0
        move    #>$266666,y1
        mpy     x0,y1,a
        move    a,x:(r7+$12)
; DC block on v (leaky mean, 2^-12, 1.7 Hz): the loop gain at DC is 1/(1 - g)
        move    x:(r7+$19),a
        move    x:(r7+$18),b
        sub     b,a
        move    a,x:(r7+$19)
        asr     #$c,a,a
        add     a,b
        move    b,x:(r7+$18)
; main write: in * mono + v; out = soft clip(0.6 v +- side)
        move    x:(r0),a
        move    x:(r0+n0),x0
        add     x0,a
        asr     a
        move    a,x0
        move    x:(r7+$0d),y1
        mpy     x0,y1,a
        move    x:(r7+$19),x0
        add     x0,a
        move    a,y:(r5)+
        move    #>$4ccccd,y1
        mpy     x0,y1,a
        move    x:(r7+$12),x1
        move    a,b
        sub     x1,b
        move    b,x:(r7+$13)  ; right, before its clip
        add     x1,a
        move    a,x0
        mpy     x0,x0,a
        move    a,x1
        mpy     x1,x0,a
        move    a,y1
        move    x0,a
        move    #>$2aaaab,y0
        mac     -y1,y0,a
        move    x:(r7+$11),y1
        move    x:(r0),b
        sub     b,a
        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
        move    x:(r7+$13),a
        move    a,x0
        mpy     x0,x0,a
        move    a,x1
        mpy     x1,x0,a
        move    a,y1
        move    x0,a
        move    #>$2aaaab,y0
        mac     -y1,y0,a
        move    x:(r7+$11),y1
        move    x:(r0),b
        sub     b,a
        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
rzdend:
        nop     
        move    r5,x:(r7+$01)
        move    #>$ffffff,m1
        move    #>$ffffff,m5
        move    #>$ffffff,m2
        move    #>$ffffff,m3
        move    #>$ffffff,m4
        rts     
; ---- subroutines (after their callers: dsp_asm encodes no backward bsr) ----
rzexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>rzxpend
        asr     b
rzxpend:
        asl     b
        rts     
rzsico:
        move    a,x1
        move    a,x0
        mpy     x0,x0,a
        move    a,y0  ; w^2
        move    #>$011111,x0
        mpy     y0,x0,a
        move    #>$155555,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    a,x0
        mpy     x1,x0,a
        move    x1,b
        sub     a,b  ; sin w
        move    b,x:(r7+$1c)
        move    #>$002d83,x0
        mpy     y0,x0,a
        move    #>$055555,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    #>$400000,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a  ; 1 - cos w
        move    a,y1
        move    x:(r7+$1d),x0
        mpy     -x0,y1,a
        add     x0,a  ; r cos w
        move    x:(r7+$1c),y1
        mpy     x0,y1,b  ; r sin w
        rts     
